using System;
using System.Reflection;
using Exoduser.UnityPort;
class VideoIntentProgram
{
 static int count;static void Check(bool value,string name){count++;if(!value)throw new Exception(name);}
 static void Permit(NativeLobbyVideo video,bool allowed){var method=typeof(NativeLobbyVideo).GetMethod("SetPlaybackAllowed");if(method==null){if(!allowed)video.Pause();}else method.Invoke(video,new object[]{allowed});}
 static void Main(string[] args){var video=new NativeLobbyVideo(new UnityEngine.Transform());video.Open("world.mp4",false,false,false);Permit(video,false);video.Player.CompletePreparation();Check(!video.Player.isPlaying,"blur while preparing must prevent asynchronous autoplay");Permit(video,true);Check(video.Player.isPlaying,"refocus resumes the intended asynchronous playback");video.Pause();Permit(video,false);Permit(video,true);Check(!video.Player.isPlaying,"manual pause survives focus cycle");video.Play();Permit(video,false);Check(!video.Player.isPlaying,"blur pauses an already playing decoder");Permit(video,true);Check(video.Player.isPlaying,"refocus resumes existing intent");Permit(video,false);video.Open("title.mp4",false,true,true);video.Player.CompletePreparation();Check(!video.Player.isPlaying,"new request preserves blur permission");Permit(video,true);Check(video.Player.isPlaying,"title may decode one frame on refocus");video.Player.EmitFrame();Check(!video.Player.isPlaying,"frozen title returns to first-frame pause");Permit(video,false);Permit(video,true);Check(!video.Player.isPlaying,"focus must not animate frozen title");video.Play();Check(video.Player.isPlaying,"explicit ENTER replaces frozen title intent");video.Player.Fail();Permit(video,false);Permit(video,true);Check(!video.Player.isPlaying,"error cannot restart on refocus");video.Dispose();Console.WriteLine("VIDEO INTENT PASS "+count);if(args.Length>0)System.IO.File.WriteAllText(args[0],"{\"passed\":"+count+",\"failed\":0}");}
}
